/* Лінійка інспектора — чиста геометрія. Нуль DOM: усі прямокутники приходять
   аргументами, тому модуль тестується в node (`tests/inspector-measure.test.mjs`).
   Збір кандидатів і малювання напрямних — не тут, а у виклику з `inspector.js`.

   Інспектор працює лише в режимі ОДНІЄЇ ітерації, де макет живий і показується
   в своїх власних CSS-пікселях, без масштабу камери. Тому тут немає ні scale, ні
   зсуву світу: числа, які прийшли, — уже ті, що бачить дизайнер.

   Прямокутники всюди у форматі `getBoundingClientRect`: `{ top, right, bottom,
   left }`. Зайві поля (`x`, `y`, `width`…) не читаються, тож DOMRect можна
   передавати як є. */

const SIDES = ['top', 'right', 'bottom', 'left'];

/* Непридатні числа ловимо на вході, а не малюємо напрямну в нікуди: NaN у
   порівняннях тихо дає false, тож кандидат просто зник би з лінійки, а дизайнер
   побачив би відстань до наступного за ним — без жодної помилки. Те саме
   формулювання, що в `rowsLayout` (`app/layout.js`) і `flowLayout`
   (`app/flow-layout.js`), бо хвороба та сама: криве число з чужих рук. */
function checkRect(rect, name) {
  if (!rect || typeof rect !== 'object') throw new Error(`лінійка: ${name} — не прямокутник`);
  for (const side of SIDES) {
    const v = rect[side];
    if (!Number.isFinite(v)) throw new Error(`лінійка: ${name}, ${side} ${v} непридатний`);
  }
  /* Вивернутий прямокутник (`right < left`) `getBoundingClientRect` не віддає
     ніколи — отже це помилка збирача, і вона мусить прозвучати: уся математика
     перетинів на такому дасть правдоподібні, але брехливі числа. */
  if (rect.right < rect.left || rect.bottom < rect.top) {
    throw new Error(`лінійка: ${name} вивернутий (${rect.left}..${rect.right} × ${rect.top}..${rect.bottom})`);
  }
}

/** Прямокутник `outer` повністю містить `inner` (Р3). */
function contains(outer, inner) {
  return outer.left <= inner.left && outer.right >= inner.right
    && outer.top <= inner.top && outer.bottom >= inner.bottom;
}

/** Зазор від цілі `t` до кандидата `c` у напрямку `dir`, або `null`, якщо
 *  кандидат у цьому напрямку не лежить.
 *
 *  Р4, головне правило всієї геометрії: кандидат «у напрямку» лише тоді, коли
 *  його проєкція на перпендикулярну вісь перетинається з проєкцією цілі СТРОГО
 *  більше нуля. Без цього «найближчим зверху» став би елемент десь збоку, і
 *  число було б правдою ні про що. Нуль перетину — це дотик кутом: спільної
 *  смуги, якою можна провести напрямну, немає.
 *
 *  Дотик краями (зазор рівно 0) — навпаки, СУСІД, і дуже потрібний: «між
 *  блоками нема відступу» це та відповідь, за якою лінійку й відкривають.
 *
 *  Кандидат, що ПЕРЕТИНАЄ ціль (зазор вийшов би відʼємним), тут пропускається, а
 *  не подається нулем. Дві причини: нуль завжди вигравав би `min` і затирав
 *  справжній зазор до реального сусіда; і сама відповідь «0 зверху» про елемент,
 *  який лежить ПОВЕРХ цілі, неправдива — він не зверху, він на ній. */
function gapTo(t, c, dir) {
  if (dir === 'top' || dir === 'bottom') {
    if (Math.min(t.right, c.right) - Math.max(t.left, c.left) <= 0) return null;
    if (dir === 'top') return c.bottom <= t.top ? t.top - c.bottom : null;
    return c.top >= t.bottom ? c.top - t.bottom : null;
  }
  if (Math.min(t.bottom, c.bottom) - Math.max(t.top, c.top) <= 0) return null;
  if (dir === 'left') return c.right <= t.left ? t.left - c.right : null;
  return c.left >= t.right ? c.left - t.right : null;
}

/** Зазор від цілі до ВНУТРІШНЬОГО краю контейнера (Р2). Перевірка проєкцій тут
 *  не потрібна: контейнер обіймає ціль з усіх боків за визначенням.
 *
 *  Відʼємний зазор означає, що ціль стирчить за межу контейнера (overflow). Це
 *  теж не зазор — пропускаємо, симетрично до перекриття елементів. */
function containerGap(t, box, dir) {
  const px = dir === 'top' ? t.top - box.top
    : dir === 'bottom' ? box.bottom - t.bottom
      : dir === 'left' ? t.left - box.left
        : box.right - t.right;
  return px < 0 ? null : px;
}

/**
 * Відстань від `target` до найближчого обʼєкта в кожному з чотирьох напрямків.
 *
 * `candidates` — прямокутники можливих сусідів; кого до них НЕ включати (сам
 * елемент, предків, нащадків, оверлей інспектора) вирішує викликач, бо це знання
 * про DOM. Тут відсіюються лише ті, кого видно з самої геометрії: нульового
 * розміру (схований елемент) і ті, що повністю містять ціль (Р3).
 *
 * `container` необовʼязковий: елемент у корені документа батька-обмежувача не
 * має, і `null` тут не помилка викликача.
 *
 * Повертає `{ top, right, bottom, left }`, де кожен напрямок або `null`, або
 * `{ px, kind: 'element' | 'container', index }`. `index` — позиція кандидата у
 * ВХІДНОМУ масиві (щоб викликач знав, до чого вести напрямну), для контейнера
 * `-1`. `px` — сирі пікселі, дробові: округлення робить плашка (Р5).
 *
 * При однаковій відстані перемагає ПЕРШИЙ кандидат у масиві, а сусід перемагає
 * край контейнера. Правило фіксоване, щоб напрямна не стрибала між двома
 * однаково правильними відповідями при кожному перемалюванні.
 */
export function measure(target, candidates, container = null) {
  checkRect(target, 'цільовий прямокутник');
  if (!Array.isArray(candidates)) throw new Error('лінійка: список кандидатів має бути масивом');
  candidates.forEach((cand, at) => checkRect(cand, `кандидат #${at}`));
  if (container !== null && container !== undefined) checkRect(container, 'прямокутник контейнера');

  const out = { top: null, right: null, bottom: null, left: null };

  candidates.forEach((cand, index) => {
    /* Нульовий прямокутник дає `display:none` — міряти до нього означає показати
       відстань до того, чого не видно. */
    if (cand.right - cand.left === 0 || cand.bottom - cand.top === 0) return;
    if (contains(cand, target)) return;
    for (const dir of SIDES) {
      const px = gapTo(target, cand, dir);
      if (px === null) continue;
      if (out[dir] === null || px < out[dir].px) out[dir] = { px, kind: 'element', index };
    }
  });

  /* Контейнер — після елементів і зі СТРОГИМ порівнянням: при нічиї виграє
     сусід, бо конкретний обʼєкт корисніший за межу, до якої нічого привʼязати. */
  if (container !== null && container !== undefined) {
    for (const dir of SIDES) {
      const px = containerGap(target, container, dir);
      if (px === null) continue;
      if (out[dir] === null || px < out[dir].px) out[dir] = { px, kind: 'container', index: -1 };
    }
  }

  return out;
}

/* ── Парне вимірювання ─────────────────────────────────────────────────────
   Друга механіка інспектора (як у VisBug): дизайнер КЛІКОМ вибрав один
   елемент, наводить на другий — і бачить відстань саме між цими двома. Пошуку
   мінімуму тут немає, тому й рішення інші, ніж у `measure`: там кандидата, який
   не дає осмисленого зазору, треба було відкинути, щоб він не затер справжній;
   тут відкидати нічого — обидва прямокутники назвав сам дизайнер, і на будь-який
   їхній розклад мусить бути чесна відповідь. */

/** Іменування країв по осях — щоб та сама математика працювала на X і на Y. */
const AXES = {
  x: { low: 'left', high: 'right' },
  y: { low: 'top', high: 'bottom' },
};

/** Прямокутники РОЗІЙШЛИСЬ по осі `axis`: спільної смуги немає, отже між ними
 *  зазор (можливо, нульовий — дотик краями).
 *
 *  Нестроге порівняння тут не випадкове, а та сама конвенція, що в `gapTo`:
 *  дотик краями — це сусідство з зазором 0 («між блоками нема відступу» — та
 *  відповідь, за якою інспектор і відкривають), а смуга нульової товщини
 *  напрямної не несе. Розділеність, а не знак перетину, тому що вироджений
 *  прямокутник (рядок тексту нульової висоти) дає перетин рівно 0, лежачи при
 *  цьому ВСЕРЕДИНІ чужої смуги: «зазор 0» був би про нього брехнею. */
function separated(a, b, axis) {
  const { low, high } = AXES[axis];
  return a[high] <= b[low] || b[high] <= a[low];
}

/** Одна напрямна по осі `axis`: скільки пікселів і між якими двома краями.
 *
 *  Якщо прямокутники по цій осі розійшлись — це зазор між зустрічними краями.
 *  Якщо ні — це глибина перекриття, тобто товщина спільної смуги, обмежена
 *  двома внутрішніми краями (обидва можуть належати одному прямокутнику, коли
 *  він по цій осі цілком у смузі іншого).
 *
 *  `from` — завжди край з МЕНШОЮ координатою, тому `px` невідʼємне завжди.
 *  Нічия (краї збіглися) — на користь `a`, щоб напрямна не стрибала між двома
 *  однаково правильними підписами при кожному перемалюванні. */
function spanOn(a, b, axis) {
  const { low, high } = AXES[axis];
  if (separated(a, b, axis)) {
    if (a[high] <= b[low]) {
      return { axis, px: b[low] - a[high], from: { rect: 'a', side: high }, to: { rect: 'b', side: low } };
    }
    return { axis, px: a[low] - b[high], from: { rect: 'b', side: high }, to: { rect: 'a', side: low } };
  }
  return {
    axis,
    px: Math.min(a[high], b[high]) - Math.max(a[low], b[low]),
    from: a[low] >= b[low] ? { rect: 'a', side: low } : { rect: 'b', side: low },
    to: a[high] <= b[high] ? { rect: 'a', side: high } : { rect: 'b', side: high },
  };
}

/**
 * Відстань між двома вибраними прямокутниками.
 *
 * Повертає `{ kind, outer, guides }`, де `guides` — це РІВНО ті напрямні, які
 * треба намалювати, а `kind` — що вони означають:
 *
 * - `'gap'` — одна напрямна: прямокутники перетинаються по одній осі, отже є
 *   смуга, якою можна провести лінію, і відстань — одне число (вертикальний
 *   зазор при спільній смузі по X, горизонтальний — по Y);
 * - `'diagonal'` — ДВІ напрямні (спершу X, тоді Y): спільної смуги немає ні по
 *   X, ні по Y, і одного числа просто не існує. Малюється Г-подібним кутом:
 *   горизонтальне коліно і вертикальне;
 * - `'overlap'` — дві напрямні: прямокутники налізають один на одного, і числа
 *   це ГЛИБИНА перекриття по кожній осі. Не пропускаємо, як у `measure` (там
 *   нуль вигравав би пошук мінімуму), і не подаємо мінусом: знак несе `kind`,
 *   а `px` лишається невідʼємним у всьому модулі;
 * - `'inside'` — ЧОТИРИ напрямні (top, right, bottom, left): один прямокутник
 *   повністю всередині іншого — іконка в кнопці, найзвичайніший розклад для
 *   цієї механіки. Відповідь тут не «нуль», а чотири відстані до внутрішніх
 *   країв. `outer` каже, хто саме зовнішній (`'a'` чи `'b'`); для решти
 *   розкладів `outer` — `null`. Однакові прямокутники містять один одного —
 *   зовнішнім названо `a`, усі чотири числа нульові.
 *
 * Кожна напрямна: `{ axis: 'x' | 'y', px, from, to }`, де `from` і `to` — краї
 * `{ rect: 'a' | 'b', side: 'top' | 'right' | 'bottom' | 'left' }`, між якими
 * лежить число (`from` — той, що з меншою координатою). Тобто малювальнику не
 * треба вгадувати ні кількість ліній, ні їх напрямок: усе назване. `px` — сирі
 * дробові пікселі, округлення робить плашка (Р5).
 *
 * Функція симетрична за ЧИСЛАМИ: `between(a, b)` і `between(b, a)` дають той
 * самий `kind`, ті самі числа й у тому самому порядку. Відрізняються лише мітки
 * `rect` (`'a'` ↔ `'b'`) і `outer` — тобто напрямок вимірювання, бо мітка це
 * позиція аргумента, а не сам прямокутник.
 *
 * Одне виключення з дзеркальності міток: коли два краї збіглися на одній
 * координаті (або прямокутники однакові), вони обмежують смугу однаково
 * правильно, і нічия детерміновано дістається ПЕРШОМУ аргументові — тобто після
 * перестановки мітка не перевертається. Числа й тут ті самі; детермінізм
 * важливіший за дзеркальність, бо підпис напрямної не мусить стрибати між двома
 * правильними варіантами при кожному перемалюванні.
 *
 * Вироджені (нульового розміру) прямокутники тут НЕ відкидаються, на відміну від
 * кандидатів у `measure`: там нульовий прямокутник означав схований елемент,
 * якого дизайнер не бачить, а тут він вибраний кліком — відкидати чужий вибір
 * нема за що.
 */
export function between(a, b) {
  checkRect(a, 'перший прямокутник');
  checkRect(b, 'другий прямокутник');

  /* Вкладення перевіряємо ПЕРШИМ: інакше іконка в кнопці поїхала б у
     `'overlap'` — формально правда, а користі нуль. */
  const aOuter = contains(a, b);
  if (aOuter || contains(b, a)) {
    const outer = aOuter ? 'a' : 'b';
    const inner = aOuter ? 'b' : 'a';
    const O = aOuter ? a : b;
    const I = aOuter ? b : a;
    return {
      kind: 'inside',
      outer,
      guides: [
        { axis: 'y', px: I.top - O.top, from: { rect: outer, side: 'top' }, to: { rect: inner, side: 'top' } },
        { axis: 'x', px: O.right - I.right, from: { rect: inner, side: 'right' }, to: { rect: outer, side: 'right' } },
        { axis: 'y', px: O.bottom - I.bottom, from: { rect: inner, side: 'bottom' }, to: { rect: outer, side: 'bottom' } },
        { axis: 'x', px: I.left - O.left, from: { rect: outer, side: 'left' }, to: { rect: inner, side: 'left' } },
      ],
    };
  }

  const sepX = separated(a, b, 'x');
  const sepY = separated(a, b, 'y');
  if (sepX && sepY) {
    return { kind: 'diagonal', outer: null, guides: [spanOn(a, b, 'x'), spanOn(a, b, 'y')] };
  }
  if (sepX) return { kind: 'gap', outer: null, guides: [spanOn(a, b, 'x')] };
  if (sepY) return { kind: 'gap', outer: null, guides: [spanOn(a, b, 'y')] };
  return { kind: 'overlap', outer: null, guides: [spanOn(a, b, 'x'), spanOn(a, b, 'y')] };
}
